contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address caddress, address[] memory tos, uint256 v) public payable {
        require(tos.length > 0);

        bool reverted;
        bool ret;
        try c.transfer(from, caddress, tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
        }

        assert(!reverted && ret);
    }

    receive() external payable {}
}

